const tradeInStaffList = `-- name: TradeInStaffList :many
select t.id, t.reference, t.user_id, t.device_type, t.brand, t.model, t.storage, t.declared_condition, t.imei, t.estimate_kobo, t.inspected_condition, t.offer_kobo, t.payout_method, t.bank_code, t.account_number_encrypted, t.account_number_last4, t.encryption_key_id, t.status, t.inspected_by, t.device_unit_id, t.paid_at, t.created_at, t.updated_at, t.variant_id, t.serial_number, t.store_id, t.received_at, t.received_by, t.inspected_at, t.inspection_notes, t.offer_expires_at, t.decided_at, t.account_name, t.payout_reference, t.paid_by, t.repair_job_id, st.name as store_name, u.first_name, u.last_name
from aftersales.trade_ins t
left join inventory.warehouses st on st.id = t.store_id
join identity.users u on u.id = t.user_id
where ($1::text is null or t.status = $1
       or ($1 = 'active' and t.status in ('submitted', 'estimated', 'awaiting_inspection', 'inspected', 'offer_sent', 'accepted'))
       or ($1 = 'payout_due' and t.status = 'accepted' and t.payout_method = 'bank'))
  and ($2::text is null or t.reference ilike $2 || '%' or t.imei = $2)
order by (t.status in ('submitted', 'awaiting_inspection', 'accepted')) desc, t.created_at
limit 200
`

